// ─────────────────────────────────────────────────────────────
// EDIT THESE BEFORE ACTIVATING
// ─────────────────────────────────────────────────────────────
const APP_URL      = 'https://YOUR-APP.vercel.app';   // public site, for the job links
const SUPABASE_URL = 'https://YOUR-PROJECT.supabase.co';
const SUPABASE_KEY = 'YOUR_SERVICE_ROLE_KEY';

// LinkedIn posting, via the Community Management API.
//
// AUTHOR is the *organization* URN of the Jobak page, not a person:
//   urn:li:organization:12345678
// Find the id in the page admin URL, or GET /v2/organizationAcls?q=roleAssignee
//
// TOKEN needs the `w_organization_social` scope and comes from an app with the
// Community Management API product approved. It is a 60-day token — when posts
// stop appearing, this is the first thing to check.
const LINKEDIN_AUTHOR = 'urn:li:organization:YOUR_ORG_ID';
const LINKEDIN_TOKEN  = 'YOUR_LINKEDIN_ACCESS_TOKEN';

// How many jobs to post per run. One is deliberate: the cursor rotates roles,
// so one post per run over several runs a day reads as a curated feed rather
// than a dump.
const POSTS_PER_RUN = 1;

// Only post listings collected within this window. An older job is more likely
// to be filled already, and posting filled roles is how a feed loses trust.
const MAX_AGE_DAYS = 14;

// Set false for a dry run: everything happens except the LinkedIn call and the
// mark-as-posted. Use it once before activating.
const LIVE = true;

return { json: {
  appUrl: APP_URL, supabaseUrl: SUPABASE_URL, supabaseKey: SUPABASE_KEY,
  linkedinAuthor: LINKEDIN_AUTHOR, linkedinToken: LINKEDIN_TOKEN,
  postsPerRun: POSTS_PER_RUN, maxAgeDays: MAX_AGE_DAYS, live: LIVE
} };

// Unpacks what next_linkedin_posts() selected.
//
// That function walks the role catalogue from a cursor and returns the newest
// unposted job for each role it can fill, so consecutive runs post a backend
// role, then a designer role, then a data role — rather than ten backend roles
// the day a backend-heavy collection lands.
//
// It deliberately does NOT mark anything posted. That happens after LinkedIn
// accepts, in `Mark Posted` — a queue that marks on selection silently loses a
// listing every time a post fails.
const payload = $input.first().json;
const rows = Array.isArray(payload) ? payload : (payload.body || []);

if (!Array.isArray(rows) || rows.length === 0) {
  console.log('Nothing to post: no unposted job matched any role in the rotation.');
  return [];
}

console.log('Selected ' + rows.length + ' job(s) to post');
return rows.map(j => ({ json: j }));

// Builds the post text and the LinkedIn payload.
//
// The link is a Jobak page, not the source's apply URL, for three reasons: it
// renders an Open Graph preview card we control, it works for someone with no
// account, and it is the only way to know the post did anything.
const cfg = $('Set Config').first().json;
const j = $input.item.json;

const slug = j.public_slug;
if (!slug) {
  // Every row gets a slug from a trigger, so this means the migration in
  // supabase/public-jobs.sql has not been applied.
  throw new Error('Job ' + j.id + ' has no public_slug — run supabase/public-jobs.sql');
}

const url = cfg.appUrl.replace(/\/$/, '') + '/jobs/' + slug;

const WORKPLACE = { remote: 'Remote', hybrid: 'Hybrid', onsite: 'On-site' };
const place = [j.location, WORKPLACE[j.job_type]].filter(Boolean).join(' · ');

// Hashtags from the job's own tech stack, plus two constants. Capped at five:
// LinkedIn stops rewarding them well before that and a wall of tags reads as
// spam.
const tagWords = Array.isArray(j.tech_stack) ? j.tech_stack.slice(0, 3) : [];
const hashtags = tagWords
  .map(t => '#' + String(t).replace(/[^a-zA-Z0-9]/g, ''))
  .filter(t => t.length > 2)
  .concat(['#hiring', '#jobs'])
  .join(' ');

const lines = [
  j.title + ' — ' + (j.company || 'Confidential'),
  '',
  place,
];
if (j.salary_text) lines.push('💰 ' + j.salary_text);
lines.push('', 'Details and apply 👇', url, '', hashtags);

const text = lines.join('\n');

/*
 * LinkedIn's /rest/posts format. `commentary` carries the text and
 * `content.article` is what makes the preview card render — without it the URL
 * appears as a bare string and engagement collapses.
 */
const body = {
  author: cfg.linkedinAuthor,
  commentary: text,
  visibility: 'PUBLIC',
  distribution: { feedDistribution: 'MAIN_FEED', targetEntities: [], thirdPartyDistributionChannels: [] },
  content: {
    article: {
      source: url,
      title: (j.title + ' at ' + (j.company || 'Confidential')).substring(0, 100),
      description: (place || 'New opening').substring(0, 250)
    }
  },
  lifecycleState: 'PUBLISHED',
  isReshareDisabledByAuthor: false
};

return { json: { jobId: j.id, title: j.title, url, text, body, live: cfg.live } };

// Honours the dry-run switch, and normalises both paths to one shape.
//
// A dry run is not a nicety here: the first live post goes to a real company
// page, and an author URN or token that is wrong should be found before it is
// found publicly.
const cfg = $('Set Config').first().json;
const req = $('Build Post').item.json;

if (!cfg.live) {
  console.log('DRY RUN — would post:\n' + req.text);
  return { json: { ...req, posted: false, dryRun: true, postUrn: null } };
}

const res = $input.item.json;
// The post URN comes back in the `x-restli-id` header; the body is empty on
// success, so a 2xx with no id still counts as posted.
const headers = res.headers || {};
const urn = headers['x-restli-id'] || headers['X-RestLi-Id'] || null;
const status = res.statusCode || res.status || 0;
const ok = status >= 200 && status < 300;

if (!ok) {
  console.log('LinkedIn refused the post (' + status + '): ' + JSON.stringify(res.body || res).substring(0, 400));
}

return { json: { ...req, posted: ok, dryRun: false, postUrn: urn, status } };

// Marks the job posted — only when LinkedIn actually accepted it.
//
// Returning [] on failure stops the branch, so the job stays unposted and the
// next run picks it up again. That is the whole reason selection and marking
// are separate steps.
const j = $input.item.json;

if (!j.posted) {
  console.log((j.dryRun ? 'Dry run' : 'Post failed') + ' — leaving "' + j.title + '" unposted.');
  return [];
}

console.log('Posted: ' + j.title + ' -> ' + j.url);
return { json: { p_job_id: j.jobId, p_post_url: j.postUrn ? ('https://www.linkedin.com/feed/update/' + j.postUrn) : null } };
